@sig trait FlightReadinessOwner_Api {
  def id: Art.BridgeId
  def navigationIn_Id : Art.PortId
  def flightControlIn_Id : Art.PortId
  def batteryIn_Id : Art.PortId
  def readinessOut_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var readinessOut: Base_Types.Boolean = $

  def put_readinessOut(value : Base_Types.Boolean) : Unit = {
    Contract(
      Modifies(readinessOut),
      Ensures(
        readinessOut == value
      )
    )
    Spec {
      readinessOut = value
    }

    Art.putValue(readinessOut_Id, Base_Types.Boolean_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

